# Concatenates the interactive layer's modules, in boot order, into runtime/interactive.bundle.js so one request replaces 24.
# boot.js loads the bundle when it exists and falls back to the individual files. Rebuild after any edit: .\tools\build-bundle.ps1
$ErrorActionPreference = 'Stop'
$IW = Split-Path -Parent $PSScriptRoot; $utf8 = New-Object Text.UTF8Encoding($false)
$boot = [IO.File]::ReadAllText((Join-Path $IW 'runtime\boot.js'), $utf8)
$m = [regex]::Match($boot, "var FILES = \[([\s\S]*?)\];"); if (-not $m.Success) { throw 'FILES list not found in boot.js' }
$files = [regex]::Matches($m.Groups[1].Value, "'([^']+)'") | ForEach-Object { $_.Groups[1].Value }
$sb = New-Object Text.StringBuilder; [void]$sb.AppendLine("/* GENERATED by tools/build-bundle.ps1 from $($files.Count) modules, in boot order. Do not edit; edit the modules and rebuild. */")
foreach ($f in $files) { $t = [IO.File]::ReadAllText((Join-Path $IW $f), $utf8); [void]$sb.AppendLine("/* ---- $f ---- */"); [void]$sb.AppendLine($t); [void]$sb.AppendLine(';') }
[IO.File]::WriteAllText((Join-Path $IW 'runtime\interactive.bundle.js'), $sb.ToString(), $utf8)
"bundle: $($files.Count) modules, $([Math]::Round($sb.Length / 1KB)) KB"
